local cache = {}
local function nums(s)
	local t = {}
	for v in s:gmatch("[^,]+") do
		table.insert(t, tonumber(v))
	end
	return t
end

-- Las piezas de un modelo: {name, level, shape, offset, size, color, mat, tr}
function TowerGear.parts(name)
	if cache[name] then
		return cache[name]
	end
	local list = {}
	for line in (TowerGear.data[name] or ""):gmatch("[^\n]+") do
		local n, lv, shape, cf, size, col, mat, tr = line:match("^([^;]+);([^;]+);(%a);([^;]+);([^;]+);([^;]+);([^;]+);([^;]+)$")
		if n then
			local c, s, rgb = nums(cf), nums(size), nums(col)
			local off = #c >= 12 and CFrame.new(table.unpack(c, 1, 12)) or CFrame.new(c[1], c[2], c[3])
			if shape == "c" then
				off *= CFrame.Angles(0, 0, math.pi / 2) -- (Blender: eje Z; Roblox: el cilindro va por X)
			end
			table.insert(list, {
				name = n, level = lv, shape = shape, offset = off, size = Vector3.new(s[1], s[2], s[3]),
				color = Color3.fromRGB(rgb[1], rgb[2], rgb[3]), mat = Enum.Material[mat] or Enum.Material.SmoothPlastic, tr = tonumber(tr) or 0,
			})
		end
	end
	cache[name] = list
	return list
end

return TowerGear
